import *as T from'three';import {OrbitControls}from'three/addons/controls/OrbitControls.js';import{STLLoader}from'three/addons/loaders/STLLoader.js';import{projectionPath}from'./optics.js';
const root='assets/projection-prototype/',scene=new T.Scene();scene.background=new T.Color('#101b22');const camera=new T.PerspectiveCamera(38,innerWidth/innerHeight,1,3000);camera.up.set(0,0,1);camera.position.set(690,-780,460);const renderer=new T.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));document.querySelector('#view').append(renderer.domElement);const controls=new OrbitControls(camera,renderer.domElement);controls.target.set(0,0,45);scene.add(new T.HemisphereLight(0xffffff,0x657580,2.5));const l=new T.DirectionalLight(0xffffff,3);l.position.set(300,-400,700);scene.add(l);const grid=new T.GridHelper(600,24,0x617d81,0x263c44);grid.rotation.x=Math.PI/2;grid.position.z=-182;scene.add(grid);
const assetVersion=Date.now().toString(),assetURL=path=>root+path+'?v='+assetVersion;
const manifest=await fetch(assetURL('parts.json'),{cache:'no-store'}).then(r=>r.json()),state=await fetch(assetURL('layout.json'),{cache:'no-store'}).then(r=>r.json()),meshes={};const loader=new STLLoader();
await Promise.all(manifest.parts.filter(p=>!p.template).map(async p=>{let g=await loader.loadAsync(assetURL((['head-upper','head-lower'].includes(p.name)?'smooth-head-v4/':p.name==='magnet-carrier'?'solid-seam-v2/':'assembly/')+p.name+'.stl'));g.computeVertexNormals();const c=['face','magnet-carrier','head-upper','head-lower'].includes(p.name)?0xe3e5df:p.name==='projector'?0x954c43:p.name.endsWith('-magnet')?0xd9b562:p.name.includes('glass')?0xe9ca81:p.print?0x59939a:0xa6afb8;const m=new T.Mesh(g,new T.MeshStandardMaterial({color:c,roughness:p.name.includes('glass')?.25:.6,metalness:p.print?0:.3,side:T.DoubleSide}));m.name=p.name;scene.add(m);meshes[p.name]=m;}));
meshes.head=new T.Group();meshes.head.name='head-shell-group';scene.add(meshes.head);meshes.head.add(meshes['head-upper'],meshes['head-lower']);
const points=[],pos=meshes.face.geometry.attributes.position;for(let i=0;i<pos.count;i+=Math.ceil(pos.count/50)){let p=projectionPath(state,new T.Vector3().fromBufferAttribute(pos,i));if(p)for(let j=1;j<p.legs.length;j++)points.push(...p.legs[j-1].toArray(),...p.legs[j].toArray());}const rays=new T.LineSegments(new T.BufferGeometry().setAttribute('position',new T.Float32BufferAttribute(points,3)),new T.LineBasicMaterial({color:0xf1c15e,transparent:true,opacity:.25}));scene.add(rays);
for(let key of ['head','face'])document.getElementById(key).onchange=e=>meshes[key].visible=e.target.checked;document.getElementById('rays').onchange=e=>rays.visible=e.target.checked;document.getElementById('hardware').onchange=e=>{for(let p of manifest.parts)if(!p.print&&!p.template&&meshes[p.name])meshes[p.name].visible=e.target.checked;};for(let[key,position]of Object.entries({front:[850,0,100],side:[0,-850,120],oblique:[690,-780,460]}))document.getElementById(key).onclick=()=>{camera.position.set(...position);controls.target.set(0,0,45);controls.update();};document.getElementById('parts').innerHTML=manifest.parts.filter(p=>p.print).map(p=>`<p><a href="${root}${['head-upper','head-lower'].includes(p.name)?'smooth-head-v4/print/':p.name==='magnet-carrier'?'solid-seam-v2/print/':'print/'}${p.name}.stl" download>${p.name}.stl</a></p>`).join('');document.getElementById('status').textContent=`${manifest.parts.filter(p=>p.print).length}個の印刷部品。顔は形状確認用の単色表示です。光路表示は幾何モデルで、実際の焦点・光量を表しません。`;
function resize(){renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();}addEventListener('resize',resize);resize();renderer.setAnimationLoop(()=>{controls.update();renderer.render(scene,camera)});

function exploded(){const on=document.getElementById('explode-face').checked;meshes.face.position.x=on?85:0;if(meshes['magnet-carrier'])meshes['magnet-carrier'].position.x=on?85:0;for(let i=0;i<4;i++)meshes['magnet-clear-'+i+'-face-magnet'].position.x=on?85:0;rays.visible=!on&&document.getElementById('rays').checked;document.getElementById('rays').disabled=on;}
document.getElementById('explode-face').onchange=exploded;
document.getElementById('magnet-view').onclick=()=>{document.getElementById('explode-face').checked=true;exploded();document.getElementById('head').checked=false;meshes.head.visible=false;document.getElementById('face').checked=true;meshes.face.visible=true;camera.position.set(-110,-260,185);controls.target.set(75,-15,160);controls.update();};

document.getElementById("head-connection-view").onclick=()=>{document.getElementById("explode-face").checked=false;exploded();document.getElementById("face").checked=false;meshes.face.visible=false;document.getElementById("head").checked=true;meshes.head.visible=true;document.getElementById("rays").checked=false;rays.visible=false;camera.position.set(300,-240,190);controls.target.set(-40,0,120);controls.update();};


let headSplit=false;
document.getElementById('head-split-view').onclick=()=>{headSplit=!headSplit;document.getElementById('explode-face').checked=false;exploded();meshes['head-upper'].position.z=headSplit?85:0;for(const[n,m]of Object.entries(meshes)){if(n==='mirror-glass'||n.startsWith('printed-mirror-')||n.startsWith('mirror-head-'))m.position.z=headSplit?85:0;if(n.startsWith('head-seam-bolt-')||n.startsWith('head-seam-washer-'))m.position.z=headSplit?105:0;if(n.endsWith('-head-magnet')){m.geometry.computeBoundingBox();if(m.geometry.boundingBox.getCenter(new T.Vector3()).z>165)m.position.z=headSplit?85:0;}if(n.endsWith('-face-magnet'))m.visible=!headSplit;}meshes.face.visible=!headSplit;if(meshes['magnet-carrier'])meshes['magnet-carrier'].visible=!headSplit;document.getElementById('face').checked=!headSplit;document.getElementById('rays').checked=false;rays.visible=false;camera.position.set(420,-420,280);controls.target.set(-20,0,200);controls.update();document.getElementById('head-split-view').textContent=headSplit?'後頭部を組立位置へ戻す':'後頭部の上下分割を見る';};

// v10: nominal sampled obstruction locations, not an irradiance simulation.
let shadowMarkers;
document.getElementById('shadow-view').onclick=async()=>{
 if(!shadowMarkers){const p=await fetch(root+'face-v12/shadow-points.json').then(r=>r.json());shadowMarkers=new T.Points(new T.BufferGeometry().setAttribute('position',new T.Float32BufferAttribute(p.flat(),3)),new T.PointsMaterial({color:0xff5544,size:1.4,depthTest:false,transparent:true,opacity:.65}));shadowMarkers.renderOrder=5;scene.add(shadowMarkers);}
 if(headSplit)document.getElementById('head-split-view').click();
 document.getElementById('explode-face').checked=false;exploded();meshes.face.visible=true;document.getElementById('face').checked=true;meshes.head.visible=false;document.getElementById('head').checked=false;rays.visible=false;document.getElementById('rays').checked=false;
 shadowMarkers.visible=true;camera.position.set(650,0,157);controls.target.set(30,0,157);controls.update();document.getElementById('status').textContent='v12：変更部品による遮蔽は255,542点の計算光路で0。点光源・公称配置の離散確認です。接着剤のはみ出し、実際の透過率・明るさ・強度は未検証です。';
};
for(const id of ['front','side','oblique','magnet-view','head-split-view','head-connection-view','explode-face'])document.getElementById(id).addEventListener('click',()=>{if(shadowMarkers)shadowMarkers.visible=false;});

const {installCeiling}=await import('./prototype-ceiling.js');
installCeiling({scene,camera,controls,meshes,manifest,state,rays,renderer});
import {installFacePreview} from './prototype-face-preview.js?revision=face-v12';
installFacePreview({scene,camera,controls,meshes,manifest,state,rays,assetVersion});

import {installFaceRemoval} from "./prototype-face-removal.js?revision=face-v12-release2";
installFaceRemoval({meshes,camera,controls,rays});
